def build_scenario(
    qid: str,
    filter_name: str,
    title: str,
    question: str,
    domain: str,
    mode: str,
    expected_source: str,
    target_surface: list,
    query_type: str,
    difficulty: str,
    purpose: str,
    expected_behavior: str,
    expected_evidence: str,
    xai_expected: bool = True,
    answerability: str = "ANSWERABLE",
    offline_available: bool = True,
    tags: list = None,
    scenario_group_id: str = None,
    variant_id: str = None,
    supporting_paper_ids: list = None,
    supporting_titles: list = None,
    supporting_topics: list = None,
    status: str = "NOT_TESTED",
    is_known_good: bool = False,
    search_id: str = None,
    execution_id: str = None,
    answer_id: str = None,
    claims_count: int = 0,
    citations_count: int = 0,
    latency_ms: int = 0
):
    return {
        "question_id": qid,
        "filter": filter_name,
        "title": title,
        "question": question,
        "domain": domain,
        "mode": mode,
        "expected_source": expected_source,
        "target_surface": target_surface,
        "query_type": query_type,
        "difficulty": difficulty,
        "purpose": purpose,
        "expected_behavior": expected_behavior,
        "expected_evidence": expected_evidence,
        "xai_expected": xai_expected,
        "answerability": answerability,
        "offline_available": offline_available,
        "tags": tags or [],
        "scenario_group_id": scenario_group_id,
        "variant_id": variant_id,
        "supporting_paper_ids": supporting_paper_ids or [],
        "supporting_titles": supporting_titles or [],
        "supporting_topics": supporting_topics or [],
        "status": "KNOWN_GOOD" if is_known_good else status,
        "is_known_good": is_known_good,
        "search_id": search_id or (f"srch_{uuid.uuid4().hex[:12]}" if is_known_good else None),
        "execution_id": execution_id or (f"exec_{uuid.uuid4().hex[:12]}" if is_known_good else None),
        "answer_id": answer_id or (f"ans_{uuid.uuid4().hex[:12]}" if is_known_good else None),
        "claims_count": claims_count,
        "citations_count": citations_count,
        "latency_ms": latency_ms
    }

def parse_item_tuple(item, filter_name):
    qid = item[0]
    title = item[1]
    question = item[2]
    domain = item[3]
    mode = item[4]
    expected_source = item[5]
    target_surface = item[6]
    query_type = item[7]
    difficulty = item[8]
    purpose = item[9]
    expected_behavior = item[10]
    expected_evidence = item[11] if len(item) > 11 else ""
    xai_expected = item[12] if len(item) > 12 else True
    answerability = item[13] if len(item) > 13 else "ANSWERABLE"
    offline_available = item[14] if len(item) > 14 else True
    tags = item[15] if len(item) > 15 else []
    scenario_group_id = item[16] if len(item) > 16 else None
    variant_id = item[17] if len(item) > 17 else None
    supporting_paper_ids = item[18] if len(item) > 18 else []
    supporting_titles = item[19] if len(item) > 19 else []
    supporting_topics = item[20] if len(item) > 20 else []

    is_known_good = qid in [
        "CS-001", "CS-002", "CS-005", "CS-025",
        "RET-003", "RET-008", "RET-025",
        "RAG-002", "RAG-006", "RAG-025",
        "XAI-001", "XAI-007", "XAI-025",
        "CIT-001", "CIT-003", "CIT-025",
        "CLM-001", "CLM-009", "CLM-025",
        "CMP-001", "CMP-003", "CMP-025",
        "OFF-001", "OFF-002", "OFF-025",
        "ONL-001", "ONL-002", "ONL-025",
        "HYB-001", "HYB-004", "HYB-025",
        "ARC-001", "ARC-007", "ARC-025",
        "LIM-001", "LIM-021", "LIM-025",
        "EVL-001", "EVL-005", "EVL-025"
    ]
    claims_count = 9 if qid.endswith("-025") else (3 if is_known_good else 0)
    citations_count = 5 if qid.endswith("-025") else (2 if is_known_good else 0)
    latency_ms = 110 if is_known_good else 0

    return build_scenario(
        qid=qid, filter_name=filter_name, title=title, question=question,
        domain=domain, mode=mode, expected_source=expected_source,
        target_surface=target_surface, query_type=query_type, difficulty=difficulty,
        purpose=purpose, expected_behavior=expected_behavior,
        expected_evidence=expected_evidence, xai_expected=xai_expected,
        answerability=answerability, offline_available=offline_available,
        tags=tags, scenario_group_id=scenario_group_id, variant_id=variant_id,
        supporting_paper_ids=supporting_paper_ids,
        supporting_titles=supporting_titles,
        supporting_topics=supporting_topics,
        is_known_good=is_known_good,
        claims_count=claims_count,
        citations_count=citations_count,
        latency_ms=latency_ms
    )

