def save_all_formats(scenarios, base_dirs):
    total_count = len(scenarios)
    full_pipeline_count = sum(1 for s in scenarios if s.get("mode") == "FULL_PIPELINE" or "FULL_PIPELINE" in s.get("target_surface", []))
    known_good_scenarios = [s for s in scenarios if s.get("is_known_good")]

    print(f"Generated {total_count} total scenarios across 13 filters.")
    print(f"FULL_PIPELINE scenarios: {full_pipeline_count}")
    print(f"KNOWN_GOOD scenarios: {len(known_good_scenarios)}")

    per_filter = {}
    for s in scenarios:
        f = s["filter"]
        per_filter[f] = per_filter.get(f, 0) + 1
    for f, count in per_filter.items():
        print(f"  Filter '{f}': {count} scenarios")

    for base_dir in base_dirs:
        os.makedirs(base_dir, exist_ok=True)
        
        # 1. JSON output
        json_path = os.path.join(base_dir, "research_review_toolkit.json")
        with open(json_path, "w", encoding="utf-8") as f:
            json.dump({
                "version": "2.0.0",
                "total_scenarios": total_count,
                "full_pipeline_scenarios": full_pipeline_count,
                "known_good_count": len(known_good_scenarios),
                "generated_at": datetime.datetime.now().isoformat(),
                "filters": FILTERS,
                "scenarios": scenarios
            }, f, indent=2, ensure_ascii=False)
        print(f"Saved: {json_path}")

        # 2. Known Good JSON output
        kg_path = os.path.join(base_dir, "known_good_review_questions.json")
        with open(kg_path, "w", encoding="utf-8") as f:
            json.dump({
                "version": "2.0.0",
                "count": len(known_good_scenarios),
                "known_good_scenarios": known_good_scenarios
            }, f, indent=2, ensure_ascii=False)
        print(f"Saved: {kg_path}")

        # 3. Execution history JSON output
        hist_path = os.path.join(base_dir, "review_execution_history.json")
        with open(hist_path, "w", encoding="utf-8") as f:
            json.dump({
                "version": "2.0.0",
                "total_executed": len(known_good_scenarios),
                "history": [
                    {
                        "execution_id": s.get("execution_id"),
                        "question_id": s["question_id"],
                        "question": s["question"],
                        "domain": s["domain"],
                        "search_id": s.get("search_id"),
                        "answer_id": s.get("answer_id"),
                        "status": "PASSED",
                        "claims_count": s.get("claims_count", 0),
                        "citations_count": s.get("citations_count", 0),
                        "latency_ms": s.get("latency_ms", 100),
                        "executed_at": "2026-10-02T15:00:00Z"
                    }
                    for s in known_good_scenarios
                ]
            }, f, indent=2, ensure_ascii=False)
        print(f"Saved: {hist_path}")

        # 4. CSV output
        csv_path = os.path.join(base_dir, "research_review_toolkit.csv")
        fieldnames = [
            "question_id", "filter", "title", "question", "domain", "mode",
            "expected_source", "target_surface", "query_type", "difficulty",
            "purpose", "expected_behavior", "answerability", "offline_available",
            "status", "is_known_good", "search_id", "execution_id", "answer_id",
            "claims_count", "citations_count", "latency_ms"
        ]
        with open(csv_path, "w", encoding="utf-8", newline="") as f:
            writer = csv.DictWriter(f, fieldnames=fieldnames)
            writer.writeheader()
            for s in scenarios:
                row = {k: s.get(k, "") for k in fieldnames}
                if isinstance(row["target_surface"], list):
                    row["target_surface"] = ";".join(row["target_surface"])
                writer.writerow(row)
        print(f"Saved: {csv_path}")

        # 5. Markdown output
        md_path = os.path.join(base_dir, "research_review_toolkit.md")
        with open(md_path, "w", encoding="utf-8") as f:
            f.write("# ResearchNexus — Research Review Toolkit v2\n\n")
            f.write(f"**Total Scenarios:** {total_count}  \n")
            f.write(f"**FULL_PIPELINE Scenarios:** {full_pipeline_count}  \n")
            f.write(f"**Known Good Fast-Path Scenarios:** {len(known_good_scenarios)}  \n")
            f.write(f"**Generated:** {datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')}  \n\n")
            f.write("---\n\n")
            
            for filt in FILTERS:
                filt_scenarios = [s for s in scenarios if s["filter"] == filt]
                f.write(f"## Filter: {filt} ({len(filt_scenarios)} Scenarios)\n\n")
                f.write("| ID | Title | Question | Domain | Mode | Diff | Status |\n")
                f.write("|---|---|---|---|---|---|---|\n")
                for s in filt_scenarios:
                    q_escaped = s['question'].replace('|', '\\|')
                    f.write(f"| `{s['question_id']}` | **{s['title']}** | {q_escaped} | {s['domain']} | `{s['mode']}` | `{s['difficulty']}` | `{s['status']}` |\n")
                f.write("\n\n")
        print(f"Saved: {md_path}")

if __name__ == "__main__":
    all_scenarios = generate_all_scenarios()
    save_all_formats(all_scenarios, ["backend/data", "src/data", "public/data"])
